         */
        val `document`: kotlin.String, 
        /**
         * `unauthorized_change`, `malformed_change` or `oversized_change`.
         */
        val `reason`: kotlin.String) : CatalogEvent()
        
    {
        

        companion object
    }
    
    /**
     * A catalog link ended.
     */
    data class LinkClosed(
        /**
         * The peer, hex.
         */
        val `principal`: kotlin.String, 
        /**
         * The close code, or none when the transport was lost.
         */
        val `code`: kotlin.ULong?, 
        /**
         * The close reason (empty when lost).
         */
        val `reason`: kotlin.String) : CatalogEvent()
        
    {
        

        companion object
    }
    
    /**
     * The listener fell behind and missed this many events.
     */
    data class Lagged(
        /**
         * How many were missed.
         */
        val `missed`: kotlin.ULong) : CatalogEvent()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCatalogEvent : FfiConverterRustBuffer<CatalogEvent>{
    override fun read(buf: ByteBuffer): CatalogEvent {
        return when(buf.getInt()) {
            1 -> CatalogEvent.Violation(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> CatalogEvent.LinkClosed(
                FfiConverterString.read(buf),
                FfiConverterOptionalULong.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> CatalogEvent.Lagged(
                FfiConverterULong.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CatalogEvent): ULong = when(value) {
        is CatalogEvent.Violation -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`principal`)
                + FfiConverterString.allocationSize(value.`document`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is CatalogEvent.LinkClosed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`principal`)
                + FfiConverterOptionalULong.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is CatalogEvent.Lagged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`missed`)
            )
        }
    }

    override fun write(value: CatalogEvent, buf: ByteBuffer) {
        when(value) {
            is CatalogEvent.Violation -> {
                buf.putInt(1)
                FfiConverterString.write(value.`principal`, buf)
                FfiConverterString.write(value.`document`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is CatalogEvent.LinkClosed -> {
                buf.putInt(2)
                FfiConverterString.write(value.`principal`, buf)
                FfiConverterOptionalULong.write(value.`code`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is CatalogEvent.Lagged -> {
                buf.putInt(3)
                FfiConverterULong.write(value.`missed`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * Why a core call failed. Each variant is stable: its name is the error's code on every platform
 * (Kotlin sees `CoreException.<Variant>`).
 */
sealed class CoreException: kotlin.Exception() {
    
    /**
     * An argument does not parse (a hex id, a key, an address, an op envelope).
     */
    class InvalidArgument(
        
        /**
         * What was wrong.
         */
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The call needs a running node and this one is not started (or was stopped).
     */
    class NotRunning(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * `start` was called on a running node.
     */
    class AlreadyRunning(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The node store failed.
     */
    class Store(
        
        /**
         * The store's message.
         */
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The agent log refused or failed.
     */
    class Log(
        
        /**
         * The log's message.
         */
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The projection (export or materialize) failed.
     */
    class Projection(
        
        /**
         * The projection's message.
         */
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The catalog failed.
     */
    class Catalog(
        
        /**
         * The catalog's message.
         */
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The transport could not bind or dial.
     */
    class Transport(
        
        /**
         * The transport's message.
         */
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The platform's runtime host failed.
     */
    class RuntimeHost(
        
        /**
         * The host's message.
         */
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The platform hooks failed (for example the node key could not be loaded).
     */
    class Platform(
        
        /**
         * The hooks' message.
         */
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The node refused the request.
     */
    class Refused(
        
        /**
         * The refusal reason.
         */
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * A move ended without committing.
     */
    class MoveAborted(
        
        /**
         * The wire reason.
         */
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The node's runtime or the agent's actor stopped while the call ran.
     */
    class Stopped(
        ) : CoreException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

